css:
.hcstrategy-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce6f0 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.hcstrategy-sim-container .hcstrategy-sim-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 24px;
    box-shadow: 0 8px 20px rgba(26,58,92,0.25);
    text-align: center;
}

.hcstrategy-sim-container .hcstrategy-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.8rem;
    font-weight: 700;
}

.hcstrategy-sim-container .hcstrategy-sim-subtitle {
    margin: 0;
    font-size: 1rem;
    opacity: 0.85;
}

.hcstrategy-sim-container .hcstrategy-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #555;
    margin-bottom: 24px;
    font-weight: 600;
}

.hcstrategy-sim-container .hcstrategy-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.hcstrategy-sim-container .hcstrategy-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 20px 16px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    transition: transform 0.3s ease;
    text-align: center;
    border-top: 4px solid #2c8c99;
}

.hcstrategy-sim-container .hcstrategy-sim-status-card:hover {
    transform: translateY(-4px);
}

.hcstrategy-sim-container .hcstrategy-card-budget { border-top-color: #27ae60; }
.hcstrategy-sim-container .hcstrategy-card-employees { border-top-color: #2980b9; }
.hcstrategy-sim-container .hcstrategy-card-brand { border-top-color: #8e44ad; }
.hcstrategy-sim-container .hcstrategy-card-enps { border-top-color: #e67e22; }
.hcstrategy-sim-container .hcstrategy-card-turnover { border-top-color: #e74c3c; }
.hcstrategy-sim-container .hcstrategy-card-capability { border-top-color: #2c8c99; }

.hcstrategy-sim-container .hcstrategy-sim-label {
    color: #5f6a75;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.hcstrategy-sim-container .hcstrategy-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #2c3e50;
}

.hcstrategy-sim-container .hcstrategy-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #1a3a5c;
}

.hcstrategy-sim-container .hcstrategy-sim-briefing h3 {
    color: #1a3a5c;
    margin-top: 0;
    margin-bottom: 12px;
    font-size: 1.15rem;
}

.hcstrategy-sim-container .hcstrategy-sim-briefing div {
    color: #555;
    line-height: 1.6;
    font-size: 0.95rem;
}

.hcstrategy-sim-container .hcstrategy-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.hcstrategy-sim-container .hcstrategy-sim-controls h3 {
    color: #1a3a5c;
    margin-top: 0;
    margin-bottom: 20px;
    font-size: 1.1rem;
}

.hcstrategy-sim-container .hcstrategy-sim-decision-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 16px;
}

.hcstrategy-sim-container .hcstrategy-sim-decision-group label {
    display: block;
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.hcstrategy-sim-container .hcstrategy-sim-decision-group .form-control {
    border-radius: 8px;
    border: 2px solid #dce6f0;
    padding: 8px 12px;
    font-size: 0.9rem;
}

.hcstrategy-sim-container .hcstrategy-sim-decision-group .form-control:focus {
    border-color: #2c8c99;
    box-shadow: 0 0 0 3px rgba(44,140,153,0.15);
}

.hcstrategy-sim-container .hcstrategy-sim-chart {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    height: 320px;
}

.hcstrategy-sim-container .hcstrategy-sim-history {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

@media (max-width: 768px) {
    .hcstrategy-sim-container .hcstrategy-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .hcstrategy-sim-container .hcstrategy-sim-decision-row {
        grid-template-columns: 1fr;
    }
    .hcstrategy-sim-container .hcstrategy-sim-value {
        font-size: 1.3rem;
    }
}
/* EQIL 2026-10-28: focus ring, reduced motion, debrief layout (append-only, namespaced) */
.hcstrategy-sim-container select:focus-visible,
.hcstrategy-sim-container input:focus-visible,
.hcstrategy-sim-container button:focus-visible {
    outline: 3px solid #1a3a5c;
    outline-offset: 2px;
}
.hcstrategy-sim-container select,
.hcstrategy-sim-container select option { color: #1f2d3a; background-color: #ffffff; }
@media (prefers-reduced-motion: reduce) {
    .hcstrategy-sim-container *, .hcstrategy-sim-container *::before, .hcstrategy-sim-container *::after {
        transition: none !important; animation: none !important;
    }
}
.hcstrategy-debrief-pillars { list-style: none; padding: 0; margin: 0.5rem 0 1rem; display: flex; flex-wrap: wrap; gap: 0.5rem; }
.hcstrategy-debrief-pillars li { background: #ffffff; color: #1f2d3a; border: 1px solid #c8d3df; border-radius: 6px; padding: 0.35rem 0.6rem; }
.hcstrategy-debrief h4 { font-size: 1rem; margin-top: 0.75rem; color: #1a3a5c; }
/* EQIL 2026-11-05 (front-design, append-only, namespaced).
   Subject: a CPO deciding four quarters of people policy before a board-ordered layoff. Register: a people-analytics
   board pack, calm and dense. Signature: the quarter result line (pillars behind the score), kept on screen.
   One accent, the author navy #1a3a5c (dark twin #89aacd). Measured: ink #1f2d3a 14.0:1, ink-2 #3d4651 9.6:1 and
   accent 11.6:1 on #ffffff; dark ink #f0f0ff 15.1:1, ink-2 #c9cce0 10.7:1, accent #89aacd 7.1:1 on #1a1a2e;
   event #6b3f00 on #fff4e0 8.3:1, dark #f2c98a on #2a2418 9.9:1. Chart series 6.0:1 or more on their panel. */
.hcstrategy-sim-container {
    --hc-ink: #1f2d3a; --hc-ink-2: #3d4651; --hc-accent: #1a3a5c; --hc-surface: #ffffff; --hc-line: #d6dbe3;
    --hc-s1: #1a3a5c; --hc-s2: #a14a00; --hc-s3: #b3261e;
    background: transparent;
}
.hcstrategy-sim-container .hcstrategy-sim-header { background: var(--hc-accent); box-shadow: none; border-radius: 8px; }
.hcstrategy-sim-container .hcstrategy-sim-subtitle { opacity: 1; }
.hcstrategy-sim-container .hcstrategy-sim-period-counter { color: var(--hc-ink); }
.hcstrategy-sim-container .hcstrategy-sim-status-card { border: 1px solid var(--hc-line); box-shadow: none; border-radius: 8px; }
.hcstrategy-sim-container .hcstrategy-sim-status-card:hover { transform: none; }
.hcstrategy-sim-container .hcstrategy-sim-label { text-transform: none; letter-spacing: 0; color: var(--hc-ink-2); font-size: 13px; }
.hcstrategy-sim-container .hcstrategy-sim-value { color: var(--hc-ink); font-variant-numeric: tabular-nums; }
.hcstrategy-sim-container .hcstrategy-sim-briefing,
.hcstrategy-sim-container .hcstrategy-sim-controls,
.hcstrategy-sim-container .hcstrategy-sim-history,
.hcstrategy-sim-container .hcstrategy-sim-chart { box-shadow: none; border: 1px solid var(--hc-line); border-radius: 8px; }
.hcstrategy-sim-container .hcstrategy-sim-briefing div { color: var(--hc-ink-2); }
.hcstrategy-sim-container .hcstrategy-sim-decision-group .form-control { border-color: #8a93a6; height: auto; min-height: 44px; }
.hcstrategy-sim-container .hcstrategy-sim-result { background: var(--hc-surface); border: 1px solid var(--hc-line); border-radius: 8px; padding: 16px 24px; margin-bottom: 24px; }
.hcstrategy-sim-container .hcstrategy-sim-result[hidden] { display: none; }
.hcstrategy-sim-container .hcstrategy-sim-result-title { font-size: 16px; font-weight: 600; color: var(--hc-accent); margin: 0 0 8px; }
.hcstrategy-sim-container .hcstrategy-sim-result-pillars { list-style: none; padding: 0; margin: 0 0 8px; display: flex; flex-wrap: wrap; gap: 8px 24px; }
.hcstrategy-sim-container .hcstrategy-sim-result-pillars li { color: var(--hc-ink-2); font-size: 14px; }
.hcstrategy-sim-container .hcstrategy-sim-result-pillars strong { color: var(--hc-ink); font-variant-numeric: tabular-nums; margin-left: 4px; }
.hcstrategy-sim-container .hcstrategy-sim-result-rule { color: var(--hc-ink-2); font-size: 14px; margin: 0; }
.hcstrategy-sim-container .hcstrategy-sim-result-event { background: #fff4e0; color: #6b3f00; border: 1px solid #c79a4a; border-radius: 6px; padding: 8px 12px; margin: 8px 0 0; font-size: 14px; }
/* Dark twin: the platform dark theme forces headings near-white and labels grey, so every panel here goes dark too. */
html.cyberpunk-dark .hcstrategy-sim-container {
    --hc-ink: #f0f0ff; --hc-ink-2: #c9cce0; --hc-accent: #89aacd; --hc-surface: #1a1a2e; --hc-line: #3b3f5c;
    --hc-s1: #89aacd; --hc-s2: #f0a35e; --hc-s3: #ff8a80;
    color-scheme: dark;
}
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-header { background: #12122a !important; border: 1px solid var(--hc-line); }
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-status-card,
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-briefing,
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-controls,
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-history,
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-chart,
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-result { background: var(--hc-surface) !important; border-color: var(--hc-line) !important; }
html.cyberpunk-dark .hcstrategy-sim-container :is(h1, h3, .hcstrategy-sim-result-title) { color: var(--hc-ink) !important; }
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-result-title { color: var(--hc-accent) !important; }
html.cyberpunk-dark .hcstrategy-sim-container :is(.hcstrategy-sim-briefing div, .hcstrategy-sim-label, .hcstrategy-sim-result-pillars li, .hcstrategy-sim-result-rule, .form-text, label) { color: var(--hc-ink-2) !important; }
html.cyberpunk-dark .hcstrategy-sim-container :is(.hcstrategy-sim-value, .hcstrategy-sim-period-counter, .hcstrategy-sim-result-pillars strong, .hcstrategy-sim-briefing strong) { color: var(--hc-ink) !important; }
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-result-event { background: #2a2418 !important; color: #f2c98a !important; border-color: #6b5a3a !important; }
html.cyberpunk-dark .hcstrategy-sim-container .hcstrategy-sim-decision-group .form-control { border-color: #6b7385; }
html.cyberpunk-dark .hcstrategy-sim-container select:focus-visible,
html.cyberpunk-dark .hcstrategy-sim-container input:focus-visible,
html.cyberpunk-dark .hcstrategy-sim-container button:focus-visible { outline-color: #89aacd; }
/* 360 px: the five-column history table scrolls inside its card, never the page */
.hcstrategy-sim-container .hcstrategy-sim-history { overflow-x: auto; }
@media (max-width: 480px) {
    .hcstrategy-sim-container { padding: 12px; }
    .hcstrategy-sim-container .hcstrategy-sim-briefing,
    .hcstrategy-sim-container .hcstrategy-sim-controls,
    .hcstrategy-sim-container .hcstrategy-sim-history,
    .hcstrategy-sim-container .hcstrategy-sim-chart,
    .hcstrategy-sim-container .hcstrategy-sim-result { padding: 16px; }
}
.hcstrategy-sim-container .hcstrategy-sim-header { text-align: left; }
.hcstrategy-sim-container #nextPeriodBtn,
.hcstrategy-sim-container #undoBtn { min-height: 44px; }
html.cyberpunk-dark .hcstrategy-debrief-pillars li { background: #1a1a2e !important; color: #c9cce0 !important; border-color: #3b3f5c !important; }
html.cyberpunk-dark .hcstrategy-debrief-pillars li strong { color: #f0f0ff !important; }

