        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 50000000,
                    employeeCount: 512,
                    brandScore: 55,
                    eNPS: 22,
                    turnoverRate: 18.4,
                    capabilityScore: 35,
                    revenuePerEmployee: 180000,
                    diversityIndex: 4.5,
                    managerQuality: 45,
                    onboardingQuality: 30,
                    hireQuality: 0,
                    survivorEngagement: 0,
                    legalRisk: 0,
                    newHires: 0,
                    counterOffer: 0,
