        _paintText(state) {
            var t = this._t();
            this._renderResult(state);
            if (this._runDone(state)) { this._renderCompletion(t, state); return null; }
            var idx = Math.min(Math.max(0, (state.currentPeriod || 1) - 1), this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);
            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var brief = t(round.briefingKey);
                if (idx === 3 && state.domainState && typeof state.domainState.budget === 'number') {
                    brief += '<br><br><strong>' + t('r4_cut_line').replace('{cash}', this._money(state.domainState.budget))
                        .replace('{n}', this._pct(Math.round(this._cutPct(state.domainState.budget) * 100))) + '</strong>';
                }
                briefEl.innerHTML = brief;
            }
            // labels and option texts in place: the student's selection is kept
            [['decision1Label', 'strategicChoiceInput', round.d1], ['decision2Label', 'investmentLevelInput', round.d2], ['decision3Label', 'approachInput', round.d3]].forEach(function(it) {
                var lbl = document.getElementById(it[0]);
                if (lbl) lbl.textContent = t(it[2].labelKey);
                var sel = document.getElementById(it[1]);
                if (!sel) return;
                for (var i = 0; i < sel.options.length; i++) {
                    var o = sel.options[i];
                    it[2].options.forEach(function(opt) { if (String(opt.value) === o.value) o.textContent = t(opt.key); });
                }
