        }

        _evText(e, t) {
            var s = t(e.k);
            if (e.n !== undefined) s = s.replace('{n}', this._num(e.n));
            return s;
        }

        // The last scored quarter, kept on screen until the next submit: its score, the pillars behind it and its events.
        _renderResult(state) {
            var el = document.getElementById('quarterResult');
            if (!el) return;
            var ds = (state && state.domainState) || {};
            var hist = ds.scoreHistory || [];
            if (!hist.length || !ds.lastPillars) { el.hidden = true; el.innerHTML = ''; return; }
            var t = this._t(), self = this, p = ds.lastPillars, q = hist.length;
            var html = '<h3 class="hcstrategy-sim-result-title">' + t('res_title').replace('{q}', q).replace('{score}', hist[q - 1]) + '</h3>';
            html += '<ul class="hcstrategy-sim-result-pillars">';
            ['acq', 'cap', 'ret', 'cri', 'fin'].forEach(function(k) {
                if (typeof p[k] === 'number') html += '<li><span>' + t('pillar_' + k) + '</span> <strong>' + p[k] + '</strong></li>';
            });
            html += '</ul><p class="hcstrategy-sim-result-rule">' + t('res_rule') + '</p>';
            (ds.lastEvents || []).forEach(function(e) { html += '<p class="hcstrategy-sim-result-event">' + self._evText(e, t) + '</p>'; });
            el.innerHTML = html;
            el.hidden = false;
        }

        _relabelChart() {
            var t = this._t();
            var cv = document.getElementById('performanceChart');
            if (cv) cv.setAttribute('aria-label', t('chart_aria'));
            var ui = window.mySimulation && window.mySimulation.uiManager;
            var ch = ui && ui.charts && ui.charts.performanceChart;
            if (!ch || !ch.data) return;
            if (ch.options && ch.options.plugins && ch.options.plugins.title) ch.options.plugins.title.text = t('chart_title');
            ['ds_score', 'ds_enps', 'ds_turnover'].forEach(function(k, i) { if (ch.data.datasets[i]) ch.data.datasets[i].label = t(k); });
            if (Array.isArray(ch.data.labels)) ch.data.labels = ch.data.labels.map(function(_, i) { return t('quarter_short') + (i + 1); });
            try { ch.update(); } catch (e) {}
        }

        _updateBriefing(state) {
            var t = this._t();
            var controls = document.querySelector('.hcstrategy-sim-controls');
            var round = this._paintText(state);
            if (!round) return;
            if (controls && controls.style.display === 'none') controls.style.display = '';

            var selects = [
                { labelId: 'decision1Label', selectId: 'strategicChoiceInput', config: round.d1 },
                { labelId: 'decision2Label', selectId: 'investmentLevelInput', config: round.d2 },
                { labelId: 'decision3Label', selectId: 'approachInput', config: round.d3 }
            ];

            selects.forEach(function(item) {
                var lbl = document.getElementById(item.labelId);
                var sel = document.getElementById(item.selectId);
                if (lbl) lbl.textContent = t(item.config.labelKey);
                if (sel) {
                    sel.innerHTML = '';
                    item.config.options.forEach(function(opt) {
                        var o = document.createElement('option');
                        o.value = opt.value;
                        o.textContent = t(opt.key);
                        sel.appendChild(o);
                    });
                }
            });
        }

        // The closing debrief on the page. It reads the run from domainState when no history is passed in (the Open player
        // keeps its history outside state.history), so it renders on the platform and in the Open player alike.
        _renderCompletion(t, state) {
            var controls = document.querySelector('.hcstrategy-sim-controls');
            if (controls) controls.style.display = 'none';
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t('sim_complete_title');
            var briefEl = document.getElementById('briefingText');
            if (!briefEl) return;
            var html = '<p>' + t('sim_complete_body') + '</p>';
            var hist = state && Array.isArray(state.history) && state.history.length ? state.history : [];
            var s = this.getPerformanceSummary(hist);
            if (s && typeof s.compositeScore === 'number') html += this._debriefHTML(s);
            briefEl.innerHTML = html;
        }

        validateDecisions(decisions) {
            if (window.mySimulation && window.mySimulation.state &&
                window.mySimulation.state.currentPeriod > this.ROUNDS.length) {
                return false;
            }

            var sel1 = document.getElementById('strategicChoiceInput');
            if (sel1) decisions.strategicChoice = parseInt(sel1.value);

            var sel2 = document.getElementById('investmentLevelInput');
            if (sel2) decisions.investmentLevel = parseInt(sel2.value);

            var sel3 = document.getElementById('approachInput');
            if (sel3) decisions.approach = parseInt(sel3.value);

            var numInput = document.getElementById('budgetAllocationInput');
            if (numInput) decisions.budgetAllocation = parseInt(numInput.value);

            if (isNaN(decisions.budgetAllocation) || decisions.budgetAllocation < 0 || decisions.budgetAllocation > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return {
                period: r.period,
                quarterScore: r.score,
                overallScore: r.score,
                score: r.score,
                brandScore: r.ds.brandScore,
                eNPS: r.ds.eNPS,
                turnoverRate: r.ds.turnoverRate,
                capabilityScore: r.ds.capabilityScore,
                managerQuality: r.ds.managerQuality,
                survivorEngagement: r.ds.survivorEngagement,
                employeeCount: r.ds.employeeCount,
                budget: r.ds.budget,
                quarterCost: r.cost,
                pillars: r.pillars,
                flags: r.flags,
                eventSummary: r.eventSummary
            };
        }

        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var a = parseInt(d.strategicChoice, 10), b = parseInt(d.investmentLevel, 10), c = parseInt(d.approach, 10);
            var x = Math.max(0, Math.min(100, d.budgetAllocation)) / 100;
            var startBudget = ds.budget;
            var events = [], evKeys = [], self0 = this;
            var ev = function(k, n) { var e = { k: k }; if (n !== undefined) e.n = n; evKeys.push(e); events.push(self0._evText(e, t)); };
            ds.flags = ds.flags || {};
            ds.healthHistory = (ds.healthHistory || []).slice(0, period - 1);

            if (period === 1) {
                // Selection depth buys hire quality; high-quality channels add quality with diminishing returns but fill fewer seats.
                var hq = Math.min(100, [0, 55, 70, 88][b] + 10 * Math.sqrt(x));
                var hires = Math.round([0, 85, 70, 55][b] * (1 - 0.25 * x * x));
                var oq = [0, 40, 65, 85][c];
                ds.budget -= 2400000 + [0, 400000, 650000, 950000][b] + [0, 200000, 450000, 720000][c];
                ds.brandScore = Math.min(100, Math.round(ds.brandScore + [0, 12, 8, 10][a] + 10 * Math.sqrt(x)));
                ds.eNPS = Math.min(80, Math.round(ds.eNPS + [0, 0, 4, 2][a] + (oq - 50) * 0.08));
                ds.diversityIndex = Math.min(10, Math.round((ds.diversityIndex + [0, 0, 0.3, 1.5][a]) * 10) / 10);
                ds.turnoverRate = Math.max(5, this._r1(ds.turnoverRate - (oq - 30) * 0.06 + (70 - hq) * 0.04));
                ds.hireQuality = Math.round(hq);
                ds.onboardingQuality = oq;
                ds.newHires = hires;
                ds.employeeCount += hires;
                ds.flags.onboard30 = (c === 1);
                ds.flags.lightSelect = (b === 1);
            } else if (period === 2) {
                // Weak onboarding: a fifth of the Q1 cohort leaves in its first months, and the seats are refilled at the Q1 cost per hire.
                var early = ds.onboardingQuality < 50 ? Math.round((ds.newHires || 0) * 0.2) : 0;
                if (early > 0) { ds.newHires -= early; ds.employeeCount -= early; ds.budget -= early * 28000; }
                ds.earlyExits = early;
                // Capability builds on the Q1 hires; unfilled seats and weak onboarding drag it down.
                var gap = Math.max(0, 80 - (ds.newHires || 0));
                ds.managerQuality = Math.min(100, ds.managerQuality + [0, 0, 10, 25][b]);
                ds.capabilityScore = Math.min(100, Math.round(ds.capabilityScore + [0, 8, 4, 6][a] + [0, 10, 7, 8][c] + 12 * Math.sqrt(x) +
                    (ds.hireQuality - 60) * 0.15 + (ds.onboardingQuality - 50) * 0.15 - gap * 0.1));
                ds.eNPS = Math.min(80, Math.round(ds.eNPS + [0, 4, 1, 6][a] + [0, 0, 5, 3][c] - Math.max(0, d.budgetAllocation - 70) * 0.1 +
                    (ds.managerQuality - 50) * 0.25));
                ds.turnoverRate = Math.max(5, this._r1(ds.turnoverRate + [0, 0, -2, -1][c]));
                ds.diversityIndex = Math.min(10, Math.round((ds.diversityIndex + [0, 0.2, 0, 0.5][a]) * 10) / 10);
                if (ds.onboardingQuality < 50) {
                    ds.turnoverRate = this._r1(ds.turnoverRate + 3);
                    ev('event_onboard_debt', ds.earlyExits || 0);
                }
                ds.budget -= 3800000 + [0, 0, 268800, 1184000][b];
                ds.revenuePerEmployee += Math.round(ds.capabilityScore * 400);
                ds.flags.mgrNone = (b === 1);
            } else if (period === 3) {
                // Lag and Leverage works only as far as the non-monetary offer is real (continuous, no cliff).
                var lag = Math.max(0, Math.min(1, (d.budgetAllocation - 30) / 50));
                var ct = [0, -5, -2, 1 - 3 * lag][a];
                var ce = [0, 3, 1, -2 + 5 * lag][a];
                var cc = [0, 5000000, 2500000, -1000000][a];
                var eq = [0, 2, 5, 3][b];
                var eqc = [0, 1200000, 2000000, 800000][b];
                var rt = [0, -3, -4, -6][c];
                var re = [0, 1, 5, 7][c];
                var rc = [0, 800000, 500000, 1200000][c];
                ds.budget -= cc + eqc + rc + Math.round(1600000 * x);
                ds.turnoverRate = Math.max(5, this._r1(ds.turnoverRate + ct + rt - eq * 0.3));
                ds.eNPS = Math.min(80, Math.round(ds.eNPS + ce + re + 6 * Math.sqrt(x) + (ds.managerQuality - 50) * 0.25));
                if (ds.managerQuality < 50) {
                    ds.eNPS = Math.round(ds.eNPS - 5);
                    ds.turnoverRate = this._r1(ds.turnoverRate + 2);
                    ev('event_manager_debt');
                }
                ds.counterOffer = (c === 1) ? 1 : 0;
                ds.flags.counter = (c === 1);
                ds.flags.leadMarket = (a === 1);
            } else if (period === 4) {
                // Counter-offered flight risks leave anyway, and peers learn that threatening to quit pays.
                if (ds.counterOffer) {
                    ds.eNPS = Math.round(ds.eNPS - 6);
                    ds.capabilityScore = Math.max(0, ds.capabilityScore - 5);
                    ds.turnoverRate = this._r1(ds.turnoverRate + 3);
                    ev('event_counter_echo');
                }
                // The board sizes the cut to reach a 24-month runway: cash spent above plan in Q1 to Q3 deepens it.
                var cutPct = this._cutPct(ds.budget);
                ds.cutPct = Math.round(cutPct * 100);
                ev('event_cut_size', ds.cutPct);
                var cut = Math.round(ds.employeeCount * cutPct);
                ds.employeeCount -= cut;
                // Above-minimum severance is normally paid against a release of claims, so the legal minimum raises litigation risk.
                // A performance-based cut is only as defensible as the ratings behind it: line managers write them, so the Q2
                // manager development (calibrated ratings) lowers its disparate-impact risk; untrained managers leave it high.
                var perfRisk = 35 - Math.max(0, Math.min(15, (ds.managerQuality - 45) * 0.5));
                var legal = Math.round([0, 10, perfRisk, 15][a] + [0, 15, 0, -5][b]);
                var comm = [0, 14, 5, -8][c];
                if (ds.managerQuality < 50) comm = Math.round(comm * 0.6);
                var sevCost = cut * [0, 15000, 40000, 75000][b];
                var reCost = Math.round(Math.max(0, ds.budget) * 0.10 * x);
                // Trust built in Q1 to Q3 (eNPS, manager quality) carries into how survivors read the cut.
                var carry = Math.max(-12, Math.min(12, (ds.eNPS - 40) * 0.25)) + (ds.managerQuality - 50) * 0.3 - (ds.counterOffer ? 6 : 0);
                var surv = Math.max(0, Math.min(100, Math.round([0, 35, 42, 48][a] + [0, -12, 3, 10][b] + comm + 12 * Math.sqrt(x) + carry - (cutPct - 0.20) * 80)));
                ds.budget -= sevCost + reCost;
                ds.capabilityScore = Math.max(0, Math.round(ds.capabilityScore + [0, -12, -3, -2][a] - (cutPct - 0.20) * 50));
                ds.brandScore = Math.max(0, Math.min(100, Math.round(ds.brandScore + [0, 5, -2, -12][c] + [0, -8, 0, 3][b] - 5)));
                ds.survivorEngagement = surv;
                ds.legalRisk = legal;
                ds.turnoverRate = Math.max(5, this._r1(0.5 * ds.turnoverRate + 0.5 * (30 - surv * 0.22) + (b === 1 ? 3 : 0)));
                ds.eNPS = Math.round(0.4 * ds.eNPS + 0.6 * (surv * 0.7 - 15));
                if (legal > 25) {
                    ds.budget -= Math.round(2400000 * (legal / 100));
                    ev('event_legal_challenge');
                }
                ds.flags.hrOnly = (c === 3);
                ds.flags.legalMin = (b === 1);
                ds.flags.perfCut = (a === 2);
                ds.flags.lifo = (a === 1);
                ds.flags.legalEvent = (legal > 25);
            }

            var pillars = this._pillars(ds, period);
            var score = this._composite(pillars);
            // one entry per scored quarter, even if a quarter is scored twice
            ['scoreHistory', 'eNPSHistory', 'turnoverHistory', 'brandHistory'].forEach(function(k) { ds[k] = (ds[k] || []).slice(0, period - 1); });
            ds.scoreHistory.push(score);
            ds.eNPSHistory.push(ds.eNPS);
            ds.turnoverHistory.push(ds.turnoverRate);
            ds.brandHistory.push(ds.brandScore);
            ds.lastPillars = pillars;
            ds.lastEvents = evKeys;
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: score });

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 400);

            return { period: period, score: score, ds: ds, cost: startBudget - ds.budget, pillars: pillars,
                     flags: Object.assign({}, ds.flags), eventSummary: events.join(' ') };
        }

        _r1(v) { return Math.round(v * 10) / 10; }

        _cutPct(budget) { return Math.max(0.15, Math.min(0.35, 0.20 + (36600000 - budget) / 1000000 * 0.015)); }

        _health(ds) {
            return Math.max(0, Math.min(100, (ds.eNPS + 10) / 70 * 100)) * 0.5 +
                   Math.max(0, Math.min(100, (25 - ds.turnoverRate) / 20 * 100)) * 0.5;
        }

        // Four people pillars, acquisition, capability, retention and crisis, plus runway, each 0-100.
        _pillars(ds, period) {
            ds.healthHistory = (ds.healthHistory || []).slice(0, period - 1);
            ds.healthHistory.push(this._health(ds));
            var clamp = function(v) { return Math.max(0, Math.min(100, Math.round(v))); };
            var p = {};
            p.acq = clamp(0.35 * ds.hireQuality + 0.45 * ds.onboardingQuality + 0.2 * ds.brandScore);
            if (period >= 2) p.cap = clamp(0.5 * (ds.capabilityScore - 30) / 40 * 100 + 0.5 * (ds.managerQuality - 30) / 40 * 100);
            p.ret = clamp(ds.healthHistory.reduce(function(s, v) { return s + v; }, 0) / ds.healthHistory.length);
            if (period >= 4) p.cri = clamp((ds.survivorEngagement - 20) / 70 * 100 - (ds.legalRisk > 25 ? 10 : 0));
            p.fin = clamp((ds.budget - 20000000) / 15000000 * 100);
            return p;
        }

        // Weighted mean of the pillars reached so far, pulled toward the weakest pillar, runway included: the plan is as strong as its weakest pillar.
        _composite(p) {
            var W = { acq: 0.20, cap: 0.20, ret: 0.25, cri: 0.25, fin: 0.10 };
            var s = 0, sw = 0, mn = 100;
            Object.keys(p).forEach(function(k) {
                s += W[k] * p[k]; sw += W[k];
                mn = Math.min(mn, p[k]);
            });
            return Math.max(0, Math.min(100, Math.round(0.6 * s / sw + 0.4 * mn)));
        }

        _band(score) {
            // Bands from the 2026-11 sweep: the teaching-note play scores about 82 and the best search about 85, while random
            // play has a median near 48, a p90 near 63 and a p99 near 74, so the top band starts above the random p99.
            if (score > 75) return 'excellent';
            if (score > 55) return 'good';
            if (score > 40) return 'developing';
            return 'needs';
        }

