        getPerformanceSummary(history) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            // The run as the framework passes it; where that history is empty (the Open player keeps its own), the same
            // facts are read from domainState, which every quarter writes.
            var st = window.mySimulation && window.mySimulation.state;
            var ds = (st && st.domainState) || {};
            var rows = Array.isArray(history) ? history.filter(function(r) { return r && r.results; }) : [];
            if (!rows.length && !(ds.scoreHistory && ds.scoreHistory.length)) return {};
            var last = rows.length ? rows[rows.length - 1].results : {};
            var scores = rows.length ? rows.map(function(r) { return r.results.quarterScore || 0; }) : ds.scoreHistory.slice();
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var composite = typeof last.overallScore === 'number' ? last.overallScore : (scores[scores.length - 1] || 0);
            var p = last.pillars || ds.lastPillars || {};
            var f = last.flags || ds.flags || {};
            var tier = this._band(composite);
            var tierKey = { excellent: 'perf_excellent', good: 'perf_good', developing: 'perf_developing', needs: 'perf_needs' }[tier];

            // Turning point: the weakest people pillar, which the composite weights most.
            var names = { acq: 'pillar_acq', cap: 'pillar_cap', ret: 'pillar_ret', cri: 'pillar_cri', fin: 'pillar_fin' };
            var weakest = null;
            Object.keys(names).forEach(function(k) { if (typeof p[k] === 'number' && (weakest === null || p[k] < p[weakest])) weakest = k; });

            var insights = [];
            if (weakest !== null) insights.push(t('ins_turning').replace('{pillar}', t(names[weakest])).replace('{n}', p[weakest]));
            if (f.onboard30) insights.push(t('ins_onboard30').replace('{n}', this._num(ds.earlyExits || 0)));
            if (f.mgrNone) insights.push(t('ins_mgrnone'));
            if (f.counter) insights.push(t('ins_counter'));
            if (f.hrOnly) insights.push(t('ins_hronly'));
            if (f.legalMin) insights.push(t('ins_legalmin'));
            if (f.perfCut && f.legalEvent) insights.push(t('ins_perfcut'));
            if (f.lifo) insights.push(t('ins_lifo'));
            if (f.leadMarket) insights.push(t('ins_leadmarket'));
            if (insights.length < 3) {
                var allStrong = ['acq', 'cap', 'ret', 'cri'].every(function(k) { return typeof p[k] === 'number' && p[k] >= 70; });
                insights.push(t(allStrong ? 'ins_strong' : 'ins_balance'));
            }
            if (insights.length < 3 && typeof p.fin === 'number') insights.push(t('ins_runway').replace('{n}', p.fin));

            return {
                totalPeriods: scores.length,
                totalScore: composite,
                overallScore: composite,
                score: composite,
                composite: composite,
                compositeScore: composite,
                averageScore: Math.round(totalScore / scores.length),
                pillars: p,
                weakestPillar: weakest,
                performance: tier,
                performanceLabel: t(tierKey),
                insights: insights
            };
        }

